-- The Jade Forest: creature abilities
-- No reference scripts the zone's creatures (the Hozen, the jinyu and the Virmen, the Sha and the mogu, the Horde and Alliance
-- soldiers and the wildlife), and most had no AI: they cast their sniffed spells (creature_template spell1-8).

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '56726,58811,59037,59084,59363,59754,59772,60969,61760,62596,62945,63351,63467,65906,66106,66153,66267,66268,66270,66271,66272,66273,66274,66275,66425,66666,66911,66917';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
